using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using Microsoft.EntityFrameworkCore; using OrcaFacil.Application.Abstractions; using OrcaFacil.Domain.Entities; using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.Subscription; [Authorize] public class BillingProfileModel:PageModel{private readonly OrcaFacilDbContext _db; private readonly ICurrentUserService _current; public BillingProfileModel(OrcaFacilDbContext db,ICurrentUserService current){_db=db;_current=current;} [BindProperty] public BillingCustomerProfile Input{get;set;}=new(); public async Task OnGetAsync(CancellationToken ct){Input=await _db.BillingCustomerProfiles.SingleOrDefaultAsync(x=>x.UserId==_current.UserId&&!x.IsDeleted,ct)??new BillingCustomerProfile{UserId=_current.UserId,Email=User.FindFirst("email")?.Value,Name=User.Identity?.Name??""};} public async Task<IActionResult> OnPostAsync(CancellationToken ct){var profile=await _db.BillingCustomerProfiles.SingleOrDefaultAsync(x=>x.UserId==_current.UserId&&!x.IsDeleted,ct); Input.UserId=_current.UserId; Input.DocumentNumber=BrazilianDocument.Normalize(Input.DocumentNumber); Input.DocumentType=Input.PersonType==OrcaFacil.Domain.Enums.PersonType.Company?OrcaFacil.Domain.Enums.BrazilianDocumentType.CNPJ:OrcaFacil.Domain.Enums.BrazilianDocumentType.CPF; if(!BrazilianDocument.HasValidCheckDigits(Input.DocumentType,Input.DocumentNumber)){ModelState.AddModelError("Input.DocumentNumber",Input.DocumentType==OrcaFacil.Domain.Enums.BrazilianDocumentType.CNPJ?"CNPJ inválido. Informe 14 números.":"CPF inválido. Informe 11 números.");return Page();} if(profile is null)_db.BillingCustomerProfiles.Add(Input); else{profile.PersonType=Input.PersonType;profile.DocumentType=Input.DocumentType;profile.DocumentNumber=Input.DocumentNumber;profile.Name=Input.Name;profile.LegalName=Input.LegalName;profile.TradeName=Input.TradeName;profile.Email=Input.Email;profile.Phone=Input.Phone;profile.City=Input.City;profile.Address=Input.Address;profile.Touch();} await _db.SaveChangesAsync(ct); TempData["Success"]="Perfil de cobrança salvo com sucesso."; return RedirectToPage();}}
